    public Acceptance(string[] args)
    {
        if(args.Length!=3 || !System.Text.RegularExpressions.Regex.IsMatch(args[0],@"^CoffeeManager_Test_G06_\d{8}_\d{6}_[a-f0-9]{8}_demo$"))throw new ArgumentException("DB test/marker/output required");
        database=args[0];marker=args[1];output=args[2];
        connection=new SqlConnectionStringBuilder{DataSource="localhost",InitialCatalog=database,IntegratedSecurity=true,Encrypt=true,TrustServerCertificate=true,Pooling=false,ApplicationName="G06Extended"}.ConnectionString;
        factory=new ConnectionFactory(connection);
        typeof(ConnectionFactory).GetProperty("SessionInitializer",BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(factory,(Func<SqlConnection,CancellationToken,Task>)(async(c,t)=>{using var q=c.CreateCommand();q.CommandText="EXECUTE AS USER='G06Runtime';";await q.ExecuteNonQueryAsync(t);}));
        auth=new(factory);permissions=new(auth);employees=new(new(factory),permissions);accounts=new(new(factory),permissions,passwords);attendance=new(new(factory),permissions);payroll=new(new(factory),new(factory),permissions);login=new(auth,passwords);
    }
    async Task<SqlConnection> Open(bool runtime=false){var c=new SqlConnection(connection);await c.OpenAsync();if(runtime){using var q=c.CreateCommand();q.CommandText="EXECUTE AS USER='G06Runtime';";await q.ExecuteNonQueryAsync();}return c;}
    static SqlParameter P(string name,object? value)
    {
        if(value is decimal d)return new(name,SqlDbType.Decimal){Precision=38,Scale=18,Value=d};
        return new(name,value??DBNull.Value);
    }
    async Task<object?> Scalar(string sql,params SqlParameter[] ps){await using var c=await Open();using var q=c.CreateCommand();q.CommandText=sql;q.CommandTimeout=25;q.Parameters.AddRange(ps);return await q.ExecuteScalarAsync();}
    async Task Exec(string sql,params SqlParameter[] ps){_ = await Scalar(sql,ps);}
    static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
    async Task Case(string id,string sub,string expected,Func<Task<object?>> body)
    {
        try{var actual=await body();results.Add(new{Id=id,Subcase=sub,Expected=expected,Actual=actual,Status="PASS"});Console.WriteLine(id+" "+sub+" PASS");}
        catch(Exception e){results.Add(new{Id=id,Subcase=sub,Expected=expected,Actual=e.Message,Status="FAIL",ErrorNumber=Number(e)});Console.WriteLine(id+" "+sub+" FAIL "+Number(e));}
        Save();
    }
    static int Number(Exception e)=>e switch{SqlException s=>s.Number,UserOperationException u=>u.Error.Number,DataAccessException d=>d.Error.Number,ArgumentException=>-100,UnauthorizedAccessException=>-101,_=>0};
    async Task<int> Error(Func<Task> call,params int[] expected)
    {
        try{await call();}catch(Exception e){var n=Number(e);if(expected.Contains(n))return n;throw;}
        throw new Exception("Expected rejection, actual success");
    }
    async Task<int> RawError(string sql,int[] expected,params SqlParameter[] ps)
    {
        await using var c=await Open(true);using var q=c.CreateCommand();q.CommandText=sql;q.CommandTimeout=8;q.Parameters.AddRange(ps);
        int n;try{await q.ExecuteNonQueryAsync();throw new Exception("Expected SQL rejection, actual success");}catch(SqlException e){n=e.Number;if(!expected.Contains(n))throw;}
        using var state=c.CreateCommand();state.CommandText="SELECT @@TRANCOUNT+(SELECT open_transaction_count FROM sys.dm_exec_sessions WHERE session_id=@@SPID);";Require(Convert.ToInt32(await state.ExecuteScalarAsync())==0,"Transaction still open after SQL rejection");return n;
    }
    void Save()=>File.WriteAllText(output,JsonSerializer.Serialize(new{Database=database,Marker=marker,Runtime="G06Runtime",Cases=results},new JsonSerializerOptions{WriteIndented=true}));
    async Task<SessionContext> Admin(){var id=Convert.ToInt32(await Scalar("SELECT MIN(t.MaTK) FROM dbo.TAIKHOAN t JOIN dbo.NHANVIEN n ON n.MaNV=t.MaNV WHERE MaVT='ADMIN' AND HoatDong=1 AND DangLamViec=1"));return new(await auth.ReadIdentityAsync(id,default)??throw new Exception("No active admin"));}
