    async Task<string> BusinessHash()=>Convert.ToString(await Scalar("SELECT CONVERT(varchar(64),HASHBYTES('SHA2_256',CONVERT(varbinary(max),(SELECT (SELECT MaNVL,SoLuongTon FROM dbo.NGUYENVATLIEU ORDER BY MaNVL FOR JSON PATH) i,(SELECT MaKH,DiemTichLuy,MaHang FROM dbo.KHACHHANG ORDER BY MaKH FOR JSON PATH) p,(SELECT MaHD,TongTien,GiamGia,ThanhTien,TrangThai FROM dbo.HOADON ORDER BY MaHD FOR JSON PATH) h,(SELECT * FROM dbo.CONGNO_NCC ORDER BY MaCN FOR JSON PATH) d FOR JSON PATH,WITHOUT_ARRAY_WRAPPER))),2)"))!;
