    async Task<AttendanceRow> Clock(string code,DateTime date,string shift="CA001")=>(await attendance.ListAsync(admin,new(date.Month,date.Year,code))).Single(r=>r.WorkDate==date&&r.Shift==shift);
    async Task<PayrollRow> Commit(PayrollRequest r)
    {
        var p=await payroll.PreviewAsync(admin,r);Require(p.Snapshot.Issues.Count==0,"Preview contains issues");var normalized=r with{Regular=p.Snapshot.RegularHours,Allowance=p.Snapshot.Allowance};
        int id=int.Parse(await payroll.CommitAsync(admin,normalized,p.Token,Guid.NewGuid()));return await payroll.GetAsync(admin,id)??throw new Exception("Missing payroll");
    }
    async Task<object> Race(string resource,Func<Task> first,Func<Task> second)
    {
        await using var gate=await Open();using var transaction=gate.BeginTransaction();using var lockCmd=gate.CreateCommand();lockCmd.Transaction=transaction;
        lockCmd.CommandText="DECLARE @r int; EXEC @r=sys.sp_getapplock @Resource=@name,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=1000;SELECT @r;";lockCmd.Parameters.AddWithValue("@name",resource);Require(Convert.ToInt32(await lockCmd.ExecuteScalarAsync())>=0,"Cannot acquire race gate");
        async Task<int> Observe(Func<Task> action){try{await action();return 0;}catch(Exception e){return Number(e);}}
        var a=Observe(first);var b=Observe(second);int waiters=0;
        for(int i=0;i<35;i++){waiters=Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM sys.dm_exec_requests WHERE database_id=DB_ID() AND wait_type IS NOT NULL AND session_id<>@@SPID"));if(waiters>=2)break;await Task.Delay(100);}
        transaction.Commit();var codes=await Task.WhenAll(a,b);Require(waiters>=2,"Two SQL waiters not observed at barrier");Require(codes.Count(x=>x==0)==1,"Expected exactly one committed transaction: "+string.Join(',',codes));return new{Waiters=waiters,SqlResults=codes};
    }
    public async Task Run()
    {
        Require(Convert.ToString(await Scalar("SELECT RunId FROM dbo.G06TestMarker"))==marker,"Marker mismatch");
        await Exec("DECLARE @s binary(8)=(SELECT SecurityStamp FROM dbo.TAIKHOAN WHERE MaTK=1); EXEC dbo.sp_SetupBootstrap @Mode='ActivateDemo',@Username=N'admin',@NewHash=@hash,@MaNV='NV001',@ExpectedStamp=@s; CREATE USER G06Runtime WITHOUT LOGIN; ALTER ROLE CafeManagerApp ADD MEMBER G06Runtime;",P("@hash",passwords.Hash(password1)));
        admin=await Admin();var businessBefore=await BusinessHash();
        full=await Employee("Full-time",10000000,0);part=await Employee();cash=await Employee();store=await Employee();admin2=await Employee("Full-time",0,0);
        await Account(cash,"accept.cash","CASH",password1);await Account(store,"accept.store","STORE",password1);await Account(admin2,"accept.admin2","ADMIN",password2);
        await Test24();admin=await Admin();await Test25();await Test26();await BugRegression();
        await Case("G06","UnrelatedBalances","Inventory/points/invoices/debts unchanged",async()=>{var after=await BusinessHash();Require(businessBefore==after,"Unrelated business balances changed");return after;});
        admin.Dispose();Save();
    }
