            await Case("T26-K04",spec.Item1,"Invalid payroll request rejected",async()=>await Error(()=>payroll.PreviewAsync(admin,spec.Item2),-100,53301));
        await Case("T26-K04","DeductionExceedsGross","SQL rejects deduction above total",async()=>{var c=await Employee();return await Error(()=>payroll.PreviewAsync(admin,new(c,9,2026,0,0,0,0,0,1)),53305);});
        await Case("T26-K05","CommitTwoSessions","Two session barrier yields one payroll/snapshot",async()=>{var c=await Employee();await attendance.SaveAsync(admin,[Line(c,day)],Guid.NewGuid());var r=new PayrollRequest(c,9,2026,8,0,0,0);var p=await payroll.PreviewAsync(admin,r);var race=await Race("CafeManager:HR:Employee:"+c,()=>payroll.CommitAsync(admin,r,p.Token,Guid.NewGuid()),()=>payroll.CommitAsync(admin,r,p.Token,Guid.NewGuid()));Require(Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.BANGLUONG WHERE MaNV=@c",P("@c",c)))==1,"Duplicate payroll");return race;});
        await Case("T26-K06","SnapshotImmutableAfterProfileChange","New snapshot unchanged after profile edit; stale preview rejected",async()=>{Require(partPayroll is not null,"Part-time fixture unavailable");var before=JsonSerializer.Serialize(partPayroll.Snapshot);var row=await Row(part);await employees.SaveAsync(admin,new(row.Name,row.Phone,"Full-time",9999999,99999,"CV001"),row,Guid.NewGuid());Require(before==JsonSerializer.Serialize((await payroll.GetAsync(admin,partPayroll.Id))!.Snapshot),"Committed snapshot changed");var c=await Employee();var input=new PayrollRequest(c,9,2026,0,0,0,0);var p=await payroll.PreviewAsync(admin,input);row=await Row(c);await employees.SaveAsync(admin,new(row.Name,row.Phone,row.Contract,0,50000,row.Position),row,Guid.NewGuid());var n=await Error(()=>payroll.CommitAsync(admin,input,p.Token,Guid.NewGuid()),53303);return new{SnapshotUnchanged=true,StalePreview=n};});
        await Case("T26-K07","ClosedPayrollAndAttendance","Direct DML denied and app cannot update/delete closed work",async()=>{Require(fullPayroll is not null,"Full payroll unavailable");var dml=await RawError("UPDATE dbo.BANGLUONG SET Thuong=Thuong+1 WHERE MaBL=@i",[229],P("@i",fullPayroll.Id));var line=await Clock(full,day);var edit=new AttendanceLine(1,"Update",full,day,line.Shift,line.ClockIn,line.ClockOut,line.Status,line.Revision);var a=await Error(()=>attendance.SaveAsync(admin,[edit],Guid.NewGuid()),53202);var b=await Error(()=>attendance.SaveAsync(admin,[edit with{Action="Delete"}],Guid.NewGuid()),53202);return new{Direct=dml,Update=a,Delete=b};});
        await Case("T26-K08","PayTwoSessions","Exactly one source expense and correct amount/employee",async()=>{Require(fullPayroll is not null,"Full payroll unavailable");await Task.Delay(1100);var now=DateTime.Now;now=now.AddTicks(-(now.Ticks%TimeSpan.TicksPerSecond));var race=await Race("CafeManager:HR:Employee:"+full,()=>payroll.PayAsync(admin,fullPayroll,now,Guid.NewGuid()),()=>payroll.PayAsync(admin,fullPayroll,now,Guid.NewGuid()));Require(Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.PHIEUTHUCHI WHERE MaBL=@i AND SoTien=10800000 AND OriginKind='Payroll' AND MaDMTC='TC005'",P("@i",fullPayroll.Id)))==1,"Expense source mismatch");return race;});
        await Case("T26-K09","InjectedPostExpenseFailure","Fault after finance insert rolls back expense and receipt",async()=>{Require(partPayroll is not null,"Part payroll unavailable");await Exec("CREATE TRIGGER dbo.G06TestExpenseFault ON dbo.G03OperationReceipt AFTER INSERT AS BEGIN IF EXISTS(SELECT 1 FROM inserted WHERE Operation='PayrollPay') THROW 53499,N'G06 injected test failure',1; END");var id=Guid.NewGuid();try{var now=DateTime.Now;now=now.AddTicks(-(now.Ticks%TimeSpan.TicksPerSecond));await Error(()=>payroll.PayAsync(admin,partPayroll,now,id),53499);Require(Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.PHIEUTHUCHI WHERE MaBL=@i",P("@i",partPayroll.Id)))==0,"Stray finance expense after fault");Require(await payroll.ReceiptAsync(admin,id,"PayrollPay")==null,"Receipt after fault");return new{ExpenseCount=0,Receipt=false};}finally{await Exec("DROP TRIGGER dbo.G06TestExpenseFault");}});
        await Case("T26-K10","ZeroNetNoExpense","Zero-net label NoExpense, no finance row, direct pay rejected",async()=>{var c=await Employee();var row=await Commit(new(c,9,2026,0,0,0,0));Require(row.Amount==0&&row.Status=="NoExpense"&&row.ExpenseCode==null,"Zero net state wrong");var n=await Error(()=>payroll.PayAsync(admin,row,DateTime.Today,Guid.NewGuid()),-100);Require(Convert.ToInt32(await Scalar("SELECT COUNT(*) FROM dbo.PHIEUTHUCHI WHERE MaBL=@i",P("@i",row.Id)))==0,"Zero expense created");return new{row.Status,Error=n};});
        await Case("T26-K11","UnpaidVsPaidSource","Committed unpaid distinct from paid; finance counts once",async()=>{Require(partPayroll is not null&&fullPayroll is not null,"Payroll fixture unavailable");var p=await payroll.GetAsync(admin,partPayroll.Id);var f=await payroll.GetAsync(admin,fullPayroll.Id);Require(p!.Status=="Unpaid"&&f!.Status=="Paid","States mixed");var sum=Convert.ToDecimal(await Scalar("SELECT SUM(SoTien) FROM dbo.PHIEUTHUCHI WHERE MaBL IN(@a,@b)",P("@a",partPayroll.Id),P("@b",fullPayroll.Id)));Require(sum==10800000,"Finance double count");return new{Unpaid=p.Status,Paid=f.Status,FinanceSum=sum};});
        foreach(var code in new[]{cash,store})await Case("T26-K12","Role"+code,"CASH/STORE payroll BLL/SQL denied",async()=>{var row=await Row(code);using var s=new SessionContext((await auth.ReadIdentityAsync(row.AccountId!.Value,default))!);var a=await Error(()=>payroll.ListAsync(s,new(9,2026)),51605,51505);var b=await RawError("EXEC dbo.sp_PayrollList @Actor=@a,@Stamp=@s,@Month=9,@Year=2026",[51505,51605],P("@a",s.Identity.AccountId),P("@s",s.Identity.SecurityStamp));return new{BLL=a,SQL=b};});
        await Case("T26-K12","CommitReplayMismatchReceipt","Same request replays once; changed payload rejected; receipt readable",async()=>{var c=await Employee();var r=new PayrollRequest(c,9,2026,0,0,0,0);var p=await payroll.PreviewAsync(admin,r);var id=Guid.NewGuid();var a=await payroll.CommitAsync(admin,r,p.Token,id);var b=await payroll.CommitAsync(admin,r,p.Token,id);Require(a==b&& (await payroll.ReceiptAsync(admin,id,"PayrollCommit"))?.Code==a,"Replay/receipt mismatch");await Error(()=>payroll.CommitAsync(admin,r with{Bonus=1},p.Token,id),51608);return new{Code=a,Replay=b};});
    }
